            C#

    using System;
using System.Collections.Generic;

namespace ConvexHullDivideAndConquer {
class Program {
    static void Main(string[] args)
    {
        Point[] points = new Point[] {
            new Point(0, 0),   new Point(1, -4),
            new Point(-1, -5), new Point(-5, -3),
            new Point(-3, -1), new Point(-1, -3),
            new Point(-2, -2), new Point(-1, -1),
            new Point(-2, -1), new Point(-1, 1)
        };

        List<Point> hull = ComputeConvexHull(points);

        Console.WriteLine("Convex Hull:");
        foreach(Point p in hull)
        {
            Console.WriteLine(p.X + " " + p.Y);
        }
    }

    static List<Point> ComputeConvexHull(Point[] points)
    {
        List<Point> hull = new List<Point>();

        // Sort points by x-coordinate
        Array.Sort(points);

        // Compute upper hull
        for (int i = 0; i < points.Length; i++) {
            while (hull.Count >= 2
                   && Point.CrossProduct(
                          hull[hull.Count - 2],
                          hull[hull.Count - 1], points[i])
                          <= 0) {
                hull.RemoveAt(hull.Count - 1);
            }
            hull.Add(points[i]);
        }

        // Compute lower hull
        int lowerHullIndex = hull.Count + 1;
        for (int i = points.Length - 2; i >= 0; i--) {
            while (hull.Count >= lowerHullIndex
                   && Point.CrossProduct(
                          hull[hull.Count - 2],
                          hull[hull.Count - 1], points[i])
                          <= 0) {
                hull.RemoveAt(hull.Count - 1);
            }
            hull.Add(points[i]);
        }

        // Remove last point (it's a duplicate of the first
        // point)
        hull.RemoveAt(hull.Count - 1);

        return hull;
    }
}

class Point : IComparable<Point> {
    public int X { get; }
    public int Y { get; }

    public Point(int x, int y)
    {
        X = x;
        Y = y;
    }

    public int CompareTo(Point other)
    {
        if (X != other.X) {
            return X - other.X;
        }
        return Y - other.Y;
    }

    public static int CrossProduct(Point A, Point B,
                                   Point C)
    {
        return (B.X - A.X) * (C.Y - A.Y)
            - (B.Y - A.Y) * (C.X - A.X);
    }
}
}



